    def dfs(start):
        stack = [(start, -1)]
        visited = [False] * n
        visited[start] = True
        path = []
        while stack:
            node, parent_edge = stack.pop()
            for neighbor, edge_idx in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append((neighbor, edge_idx))
                    path.append(edge_idx)
                elif edge_idx != parent_edge:
                    cycle = []
                    current = edge_idx
                    while current != -1:
                        cycle.append(current)
                        u, v = edges[current]
                        if visited[u] and (v, current) in adj[u]:
                            current = adj[u][adj[u].index((v, current)) ^ 1][1]
                        else:
